(function(){'use strict';const $=id=>document.getElementById(id);let current='omni';function update(){const lang=$('locale').value,t=obRTLStrings[lang];obRTL.apply(document,lang);document.querySelector('h1').textContent=t.title;document.querySelector('.intro').textContent=t.intro;document.querySelector('.topline>span:last-child').textContent=t.title;document.querySelector('label').firstChild.textContent=t.language;document.querySelectorAll('[data-label]').forEach(e=>e.textContent=t[e.dataset.label]);document.querySelectorAll('[data-view]').forEach(e=>{e.textContent=t[e.dataset.view];e.classList.toggle('primary',e.dataset.view===current)});$('view-title').textContent=t[current+'Title'];$('view-description').textContent=t[current+'Text'];$('sample-title').textContent=t.sample;$('size-label').textContent=t.size;$('input-label').textContent=t.input;$('details').textContent=t.details;$('dialog-message').textContent=t.dialog;const hints=document.querySelectorAll('.hintbar>span');hints[0].textContent=t.move;hints[1].lastChild.textContent=t.select;hints[2].lastChild.textContent=t.back;$('status').textContent=''}$('locale').addEventListener('change',update);document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.view;update()}));$('previous').addEventListener('click',()=>{$('status').textContent=obRTLStrings[$('locale').value].previous});$('next').addEventListener('click',()=>{$('status').textContent=obRTLStrings[$('locale').value].next});$('details').addEventListener('click',()=>obUI.openDialog('info-dialog'));document.addEventListener('focusin',e=>document.querySelectorAll('.pad-focus').forEach(x=>{if(x!==e.target)x.classList.remove('pad-focus')}));update()})();
